insert into public.operators (id, slug, business_name, type, contact_name, phone, whatsapp, email, district, address, description, logo, verification_status, rating, review_count, years_in_business, is_demo, created_at, updated_at) values
  ('a0000000-0000-4000-8000-000000000001', 'greenleaf-kerala-tours', 'Greenleaf Kerala Tours (Demo)', 'travel_agency'::operator_type, 'Anitha Menon', '+91 90000 00001', '+91 90000 00001', 'hello@greenleaf.demo', 'Ernakulam'::district, 'MG Road, Kochi', 'Full-service agency for family holidays, honeymoons and multi-day Kerala circuits with hand-picked stays.', null, 'verified'::verification_status, 4.8, 412, 12, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('a0000000-0000-4000-8000-000000000002', 'malabar-trails', 'Malabar Trails Holidays (Demo)', 'travel_agency'::operator_type, 'Faisal Rahman', '+91 90000 00002', '+91 90000 00002', 'trips@malabartrails.demo', 'Kozhikode'::district, 'Mavoor Road, Kozhikode', 'North Kerala specialists: Wayanad, Bekal, Kannur Theyyam season and Malabar food trails.', null, 'verified'::verification_status, 4.7, 238, 8, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('a0000000-0000-4000-8000-000000000003', 'highrange-escapes', 'Highrange Escapes (Demo)', 'tour_operator'::operator_type, 'Biju Thomas', '+91 90000 00003', '+91 90000 00003', 'ride@highrange.demo', 'Idukki'::district, 'Old Munnar, Idukki', 'Independent operator running scheduled group trips to Munnar, Vagamon and Thekkady every weekend.', null, 'verified'::verification_status, 4.6, 156, 6, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('a0000000-0000-4000-8000-000000000004', 'jomon-cabs', 'Jomon Cabs (Demo)', 'vehicle_owner'::operator_type, 'Jomon Varghese', '+91 90000 00004', '+91 90000 00004', 'jomon@cabs.demo', 'Thrissur'::district, 'Swaraj Round, Thrissur', 'Owner-driver with two well-kept cars for airport runs, day trips and family tours across Kerala.', null, 'verified'::verification_status, 4.9, 87, 9, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('a0000000-0000-4000-8000-000000000005', 'coastline-coaches', 'Coastline Coaches (Demo)', 'fleet_operator'::operator_type, 'Suresh Nair', '+91 90000 00005', '+91 90000 00005', 'fleet@coastline.demo', 'Thiruvananthapuram'::district, 'Thampanoor, Thiruvananthapuram', 'Fleet of tempo travellers, tourist buses and luxury coaches for groups, pilgrimages and corporate tours.', null, 'verified'::verification_status, 4.5, 301, 15, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('a0000000-0000-4000-8000-000000000006', 'backwater-bliss', 'Backwater Bliss Houseboats (Demo)', 'tour_operator'::operator_type, 'Reena Joseph', '+91 90000 00006', '+91 90000 00006', 'stay@backwaterbliss.demo', 'Alappuzha'::district, 'Finishing Point, Alappuzha', 'Premium and deluxe houseboats on Vembanad Lake with private chefs.', null, 'pending'::verification_status, 4.4, 64, 4, true, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z')
insert into public.destinations (id, slug, name, district, tagline, description, cover_image, gallery, attractions, best_experiences, best_time_to_visit, is_featured, is_active, latitude, longitude, created_at, updated_at) values
  ('d0000000-0000-4000-8000-000000000001', 'munnar', 'Munnar', 'Idukki'::district, 'Rolling tea estates in the Western Ghats', 'At 1,600 m, Munnar is a cool hill station wrapped in emerald tea gardens, misty valleys and spice-scented air. Home to the endangered Nilgiri tahr at Eravikulam and South India’s highest peak, Anamudi.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munnar-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munnar-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munnar-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munnar-4.jpg']::text[], '[{"name":"Eravikulam National Park","description":"Grasslands that shelter the Nilgiri tahr; Neelakurinji blooms every 12 years."},{"name":"Mattupetty Dam","description":"Boating on a calm reservoir surrounded by shola forest."},{"name":"Top Station","description":"Sunrise viewpoint on the Kerala–Tamil Nadu border."},{"name":"Tea Museum","description":"Learn how Kannan Devan tea goes from leaf to cup."}]'::jsonb, array['Tea estate walks','Sunrise at Top Station','Spice garden tours','Jeep safari to Kolukkumalai']::text[], 'September to March', true, true, 10.0889, 77.0595, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000002', 'wayanad', 'Wayanad', 'Wayanad'::district, 'Forests, caves and misty peaks', 'A green plateau of coffee and pepper plantations, ancient Edakkal cave petroglyphs, wildlife sanctuaries and the heart-shaped lake on Chembra Peak.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/wayanad-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/wayanad-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/wayanad-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/wayanad-4.jpg']::text[], '[{"name":"Edakkal Caves","description":"Neolithic rock engravings reached by a short, steep climb."},{"name":"Chembra Peak","description":"Trek to the famous heart-shaped lake."},{"name":"Banasura Sagar Dam","description":"India’s largest earth dam with island-dotted views."},{"name":"Muthanga Wildlife Sanctuary","description":"Jeep safaris through elephant country."}]'::jsonb, array['Chembra trek','Plantation stays','Wildlife safari','Treehouse nights']::text[], 'October to May', true, true, 11.6854, 76.132, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000003', 'vagamon', 'Vagamon', 'Idukki'::district, 'Meadows, pine forests and paragliding', 'Quiet, rolling meadows and pine forests on the Idukki–Kottayam border. A favourite for group getaways, campfires and paragliding at the Vagamon festival.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/vagamon-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/vagamon-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/vagamon-3.jpg']::text[], '[{"name":"Vagamon Meadows","description":"Endless green slopes perfect for picnics."},{"name":"Pine Forest","description":"Cool, cinematic walks among tall pines."},{"name":"Kurisumala","description":"Hilltop pilgrimage site with sweeping views."}]'::jsonb, array['Paragliding','Camping','Pine forest walks','Off-road trails']::text[], 'August to May', true, true, 9.6862, 76.9052, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000004', 'alleppey', 'Alleppey', 'Alappuzha'::district, 'Houseboats on the backwaters', 'The “Venice of the East” — a web of lagoons, canals and paddy fields best explored on a traditional kettuvallam houseboat with Kerala meals cooked on board.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/alleppey-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/alleppey-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/alleppey-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/alleppey-4.jpg']::text[], '[{"name":"Vembanad Lake","description":"Kerala’s longest lake and the heart of houseboat cruising."},{"name":"Alappuzha Beach","description":"A 150-year-old pier and lighthouse by the sea."},{"name":"Kuttanad","description":"Farmland below sea level, framed by canals."}]'::jsonb, array['Overnight houseboat','Shikara ride','Village canoe tour','Toddy shop lunch']::text[], 'November to February', true, true, 9.4981, 76.3388, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000005', 'thekkady', 'Thekkady', 'Idukki'::district, 'Spice country and Periyar wildlife', 'Gateway to Periyar Tiger Reserve, with boat safaris on Periyar Lake, bamboo rafting, spice plantations and Kathakali performances in the evenings.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/thekkady-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/thekkady-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/thekkady-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/thekkady-4.jpg']::text[], '[{"name":"Periyar Tiger Reserve","description":"Lake cruise to spot elephants, gaur and birds."},{"name":"Spice plantations","description":"Cardamom, pepper and clove gardens."},{"name":"Bamboo rafting","description":"Full-day guided ranger expedition."}]'::jsonb, array['Boat safari','Spice tour','Elephant junction','Kalaripayattu show']::text[], 'October to June', false, true, 9.6031, 77.161, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000006', 'varkala', 'Varkala', 'Thiruvananthapuram'::district, 'Red cliffs over the Arabian Sea', 'Laterite cliffs, a bohemian café strip and a sacred beach at Papanasam. Varkala is for slow sunsets, yoga mornings and fresh seafood.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/varkala-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/varkala-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/varkala-3.jpg']::text[], '[{"name":"North Cliff","description":"Cafés and sunset views on the cliff edge."},{"name":"Janardanaswamy Temple","description":"2,000-year-old temple near the beach."},{"name":"Kappil Beach","description":"Where backwaters meet the sea."}]'::jsonb, array['Cliff-top sunsets','Surf lessons','Ayurveda','Yoga retreats']::text[], 'October to March', true, true, 8.7379, 76.7163, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000007', 'kovalam', 'Kovalam', 'Thiruvananthapuram'::district, 'Crescent beaches and a striped lighthouse', 'Three crescent beaches south of Thiruvananthapuram, famous for the Vizhinjam lighthouse, Ayurvedic resorts and calm swimming waters.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kovalam-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kovalam-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kovalam-3.jpg']::text[], '[{"name":"Lighthouse Beach","description":"Climb the lighthouse for coastal views."},{"name":"Hawa Beach","description":"Morning fishing boats and calm waters."},{"name":"Padmanabhaswamy Temple","description":"Dravidian temple in the capital, 30 minutes away."}]'::jsonb, array['Beach resorts','Ayurvedic massage','Catamaran rides']::text[], 'September to March', false, true, 8.4004, 76.9787, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000008', 'fort-kochi', 'Fort Kochi', 'Ernakulam'::district, 'Colonial lanes and Chinese fishing nets', 'A layered port town of Portuguese, Dutch and British history — Chinese fishing nets, Jew Town spice markets, art cafés and the Kochi-Muziris Biennale.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/fort-kochi-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/fort-kochi-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/fort-kochi-3.jpg']::text[], '[{"name":"Chinese fishing nets","description":"Cantilevered nets silhouetted at sunset."},{"name":"Mattancherry Palace","description":"Murals depicting the Ramayana."},{"name":"Jew Town & Paradesi Synagogue","description":"Antique shops and 16th-century synagogue."}]'::jsonb, array['Heritage walk','Kathakali show','Café hopping','Sunset at the nets']::text[], 'October to March', true, true, 9.9658, 76.2421, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000009', 'athirappilly', 'Athirappilly', 'Thrissur'::district, 'Kerala’s mightiest waterfall', 'An 80-ft cascade on the Chalakudy river framed by rainforest. Combine with Vazhachal falls and the Sholayar forest drive for a classic day trip from Kochi or Thrissur.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/athirappilly-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/athirappilly-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/athirappilly-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/athirappilly-4.jpg']::text[], '[{"name":"Athirappilly Falls","description":"Walk down to the base for the full roar."},{"name":"Vazhachal Falls","description":"Gentler falls 5 km upstream."},{"name":"Sholayar forest drive","description":"Hornbill country on the way to Valparai."}]'::jsonb, array['Waterfall trail','Rainforest drive','Birdwatching']::text[], 'June to January', true, true, 10.2851, 76.5698, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000010', 'bekal', 'Bekal', 'Kasaragod'::district, 'A seaside fort in the far north', 'Kerala’s largest fort sits on a headland above the sea. Nearby are quiet beaches, Valiyaparamba backwaters and Theyyam rituals in winter.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/bekal-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/bekal-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/bekal-3.jpg']::text[], '[{"name":"Bekal Fort","description":"17th-century keyhole-shaped fort with sea views."},{"name":"Valiyaparamba","description":"Island-studded backwaters, uncrowded."},{"name":"Ranipuram","description":"Hill station trek near the Karnataka border."}]'::jsonb, array['Fort sunset','Theyyam season','Backwater kayak']::text[], 'October to March', false, true, 12.3925, 75.0332, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000011', 'ponmudi', 'Ponmudi', 'Thiruvananthapuram'::district, 'A hairpin climb above the capital', 'A compact hill station 60 km from Thiruvananthapuram with 22 hairpin bends, tea gardens and cool clouds — perfect for a one-day escape.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/ponmudi-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/ponmudi-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/ponmudi-3.jpg']::text[], '[{"name":"Golden Valley","description":"Riverside stop at the foot of the hills."},{"name":"Meenmutty Falls","description":"Short forest trek to the falls."},{"name":"Peppara Wildlife Sanctuary","description":"Lush sanctuary along the route."}]'::jsonb, array['Hairpin drive','Trekking','Picnics']::text[], 'August to March', false, true, 8.7597, 77.1166, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000012', 'kumarakom', 'Kumarakom', 'Kottayam'::district, 'Lakeside calm and a bird sanctuary', 'On the eastern shore of Vembanad Lake, Kumarakom is known for luxury lake resorts, a migratory bird sanctuary and village life tours.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kumarakom-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kumarakom-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kumarakom-3.jpg']::text[], '[{"name":"Kumarakom Bird Sanctuary","description":"Herons, egrets and Siberian cranes in season."},{"name":"Pathiramanal Island","description":"Boat out to a quiet island on the lake."},{"name":"Village life experience","description":"Coir making, toddy tapping, fishing."}]'::jsonb, array['Lake resorts','Birdwatching','Sunset cruise']::text[], 'September to March', true, true, 9.6175, 76.4301, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000013', 'idukki', 'Idukki', 'Idukki'::district, 'Arch dams and high-range forests', 'The Idukki arch dam spans two granite hills above a vast reservoir. The district is a base for Kalvari Mount, Anchuruli tunnel and wildlife.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/idukki-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/idukki-2.jpg']::text[], '[{"name":"Idukki Arch Dam","description":"One of Asia’s highest arch dams; opens on festival days."},{"name":"Kalvari Mount","description":"Panoramic reservoir viewpoint."},{"name":"Anchuruli","description":"A rock-cut tunnel opening onto the lake."}]'::jsonb, array['Viewpoint hopping','Forest stays','Jeep trails']::text[], 'September to May', false, true, 9.8497, 76.9681, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000014', 'kozhikode', 'Kozhikode', 'Kozhikode'::district, 'Spice coast, biryani and beaches', 'The historic port where Vasco da Gama landed. Kozhikode is famous for halwa street, Malabar biryani, Kappad beach and day trips to Thusharagiri falls.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kozhikode-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kozhikode-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kozhikode-3.jpg']::text[], '[{"name":"Kozhikode Beach","description":"Evening promenade and street food."},{"name":"SM Street","description":"Sweetmeat Street for halwa and shopping."},{"name":"Thusharagiri Falls","description":"Three-tiered waterfall in the forest."}]'::jsonb, array['Food walks','Beach evenings','Heritage trail']::text[], 'October to March', false, true, 11.2588, 75.7804, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000015', 'sabarimala', 'Sabarimala', 'Pathanamthitta'::district, 'The Ayyappa pilgrimage', 'The hill shrine of Lord Ayyappa in the Periyar Tiger Reserve draws millions of devotees during the Mandala–Makaravilakku season, via the Pamba base camp.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/sabarimala-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/sabarimala-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/sabarimala-3.jpg']::text[], '[{"name":"Sannidhanam","description":"The main shrine, reached by a 5 km forest climb from Pamba."},{"name":"Pamba","description":"Base camp and sacred river."},{"name":"Erumely","description":"Traditional starting point on the old route."}]'::jsonb, array['Mandala season pilgrimage','Guided darshan logistics']::text[], 'November to January', false, true, 9.4346, 77.0814, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000016', 'munroe-island', 'Munroe Island', 'Kollam'::district, 'Canoe through village canals', 'A cluster of islets where the Kallada river meets Ashtamudi Lake. Glide through narrow canals by country boat at sunrise past coir makers and prawn farms.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munroe-island-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munroe-island-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/munroe-island-3.jpg']::text[], '[{"name":"Sunrise canoe","description":"Two-hour canal tour at dawn."},{"name":"Ashtamudi Lake","description":"Eight-armed lake, gateway to Kollam."}]'::jsonb, array['Canoe tour','Village homestay','Kollam cashew trail']::text[], 'October to March', false, true, 8.9927, 76.6145, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000017', 'nelliyampathy', 'Nelliyampathy', 'Palakkad'::district, 'Orange orchards in the clouds', 'Above Palakkad’s paddy plains, Nelliyampathy offers orange and coffee estates, Seetharkundu viewpoint and the Pothundi dam on the climb.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nelliyampathy-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nelliyampathy-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nelliyampathy-3.jpg']::text[], '[{"name":"Seetharkundu viewpoint","description":"Sheer drop over the plains."},{"name":"Pothundi Dam","description":"Earth dam at the foot of the ghat road."}]'::jsonb, array['Estate stays','Ghat road drive']::text[], 'September to March', false, true, 10.5361, 76.6936, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000018', 'nilambur', 'Nilambur', 'Malappuram'::district, 'Teak forests and a hanging bridge', 'Home to the world’s oldest teak plantation, Conolly’s Plot, a riverside hanging bridge and the Teak Museum. A peaceful forest escape in Malappuram.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nilambur-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nilambur-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/nilambur-3.jpg']::text[], '[{"name":"Conolly’s Plot","description":"Teak planted in the 1840s."},{"name":"Teak Museum","description":"The only museum of its kind."}]'::jsonb, array['Forest walks','Nilambur–Shoranur rail ride']::text[], 'October to March', false, true, 11.2765, 76.2257, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('d0000000-0000-4000-8000-000000000019', 'kannur', 'Kannur', 'Kannur'::district, 'Theyyam and drive-in beaches', 'Land of looms and lores: Muzhappilangad drive-in beach, St. Angelo Fort, handloom villages and spectacular Theyyam rituals between December and April.', 'https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kannur-1.jpg', array['https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kannur-2.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kannur-3.jpg','https://cdn.jsdelivr.net/gh/Amaljith75/Travo@9d37dbc1a869121092f90bec5beec3b410706676/assets/photos/kannur-4.jpg']::text[], '[{"name":"Muzhappilangad Beach","description":"Kerala’s longest drive-in beach."},{"name":"St. Angelo Fort","description":"Portuguese fort facing the sea."},{"name":"Theyyam","description":"Ritual dance performances in village shrines."}]'::jsonb, array['Theyyam nights','Beach drive','Handloom tour']::text[], 'November to April', false, true, 11.8745, 75.3704, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z')
insert into public.packages (id, slug, title, summary, description, destination_id, additional_destination_ids, operator_id, categories, trip_type, duration_days, duration_nights, base_price, discount_percent, min_group_size, max_group_size, vehicle_category, transport_details, accommodation, pickup_points, drop_points, pickup_districts, inclusions, exclusions, cancellation_policy, available_dates, status, is_featured, is_trending, rating, review_count, booking_count, created_at, updated_at) values
  ('b0000000-0000-4000-8000-000000000001', 'athirappilly-waterfall-day-trip', 'Athirappilly & Vazhachal Waterfall Day Trip', 'Kerala’s grandest waterfall, rainforest drive and a riverside lunch — back by evening.', 'Leave Kochi early for the 80-ft Athirappilly falls, walk down to the base viewpoint, continue to Vazhachal and drive into the Sholayar forest for hornbill spotting. A Kerala sadya lunch is served at a riverside restaurant.', 'd0000000-0000-4000-8000-000000000009', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000004', array['one_day','family','budget']::package_category[], 'private'::trip_type, 1, 0, 1499, 10, 2, 7, 'muv'::vehicle_category, 'Private AC car or Innova with driver, door pickup in Kochi or Thrissur.', 'Not applicable (day trip).', array['Kochi city','Kochi airport','Thrissur town']::text[], array['Kochi city','Kochi airport','Thrissur town']::text[], array['Ernakulam','Thrissur']::district[], array['Private AC vehicle with driver','Fuel, tolls and parking','Kerala sadya lunch','Bottled water']::text[], array['Waterfall entry tickets (₹50)','Personal expenses']::text[], 'Free cancellation up to 48 hours before departure. 50% refund within 48 hours. No refund for no-shows.', '{}'::date[], 'published'::package_status, true, true, 4.8, 96, 412, '2026-07-30T21:20:55.260Z', '2026-07-30T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000002', 'munnar-weekend-escape', 'Munnar Weekend Escape', 'Two nights in the tea hills with Eravikulam, Mattupetty and Top Station sunrise.', 'The classic Kerala hill-station weekend. Climb into the High Ranges past Cheeyappara and Valara waterfalls, stay at a valley-view resort and spend two days among tea estates, dams and viewpoints.', 'd0000000-0000-4000-8000-000000000001', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000003', array['weekend','group','family']::package_category[], 'group'::trip_type, 3, 2, 4999, 0, 6, 12, 'tempo_traveller'::vehicle_category, 'AC 12-seater Tempo Traveller from Kochi.', 'Valley-view resort, twin/triple sharing.', array['Kochi — Vyttila Hub','Aluva metro station']::text[], array['Kochi — Vyttila Hub']::text[], array['Ernakulam']::district[], array['AC Tempo Traveller','2 nights resort stay','Breakfast and dinner','Trip captain','Campfire night']::text[], array['Lunches','Entry tickets','Jeep safari (optional)']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, true, true, 4.7, 214, 980, '2026-05-11T21:20:55.260Z', '2026-05-11T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000003', 'alleppey-houseboat-overnight', 'Alleppey Premium Houseboat Overnight', 'A private kettuvallam cruise on Vembanad Lake with chef-cooked Kerala meals.', 'Board a private premium houseboat at noon and drift through Kuttanad’s canals and paddy fields. Your on-board chef prepares karimeen pollichathu and fresh appam; the boat anchors at sunset for a quiet night on the lake.', 'd0000000-0000-4000-8000-000000000004', array['d0000000-0000-4000-8000-000000000012']::uuid[], 'a0000000-0000-4000-8000-000000000006', array['couple','honeymoon','luxury','weekend']::package_category[], 'private'::trip_type, 2, 1, 7499, 15, 2, 4, 'sedan'::vehicle_category, 'Optional private sedan transfer from Kochi (add-on).', 'Private 1–2 bedroom premium houseboat with AC bedrooms.', array['Alappuzha Finishing Point jetty','Kochi (with transfer add-on)']::text[], array['Alappuzha Finishing Point jetty','Kochi (with transfer add-on)']::text[], array['Alappuzha','Ernakulam']::district[], array['Private houseboat for 22 hours','Lunch, evening snacks, dinner, breakfast','AC in bedrooms (9 pm – 6 am)','Welcome drink']::text[], array['Transfers to the jetty','Alcohol','Shikara ride']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, true, true, 4.9, 178, 640, '2026-06-20T21:20:55.260Z', '2026-06-20T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000004', 'wayanad-3-day-adventure', 'Wayanad 3-Day Adventure', 'Chembra heart-lake trek, Edakkal caves and a wildlife jeep safari.', 'For active travellers: trek Chembra Peak to the heart-shaped lake, scramble up to Edakkal’s Neolithic carvings, kayak on Pookode lake and ride into Muthanga sanctuary at dawn.', 'd0000000-0000-4000-8000-000000000002', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000002', array['adventure','multi_day','group']::package_category[], 'group'::trip_type, 3, 2, 6499, 0, 6, 14, 'tempo_traveller'::vehicle_category, 'AC Tempo Traveller from Kozhikode.', 'Plantation homestay & tented camp.', array['Kozhikode railway station','Calicut airport']::text[], array['Kozhikode railway station','Calicut airport']::text[], array['Kozhikode','Malappuram']::district[], array['Transport','2 nights stay','All meals','Trek guide & forest permits','Muthanga safari']::text[], array['Personal gear','Camera fees']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, true, 4.7, 88, 310, '2026-08-29T21:20:55.260Z', '2026-08-29T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000005', 'kerala-5-day-family-tour', 'Kerala Classic 5-Day Family Tour', 'Kochi, Munnar, Thekkady and an Alleppey houseboat — the full Kerala in one trip.', 'A comfortable, well-paced circuit for families: Fort Kochi heritage, two nights in Munnar, a spice-country night in Thekkady and a final night on a private houseboat. Private Innova with a dedicated driver throughout.', 'd0000000-0000-4000-8000-000000000001', array['d0000000-0000-4000-8000-000000000008','d0000000-0000-4000-8000-000000000005','d0000000-0000-4000-8000-000000000004']::uuid[], 'a0000000-0000-4000-8000-000000000001', array['family','multi_day']::package_category[], 'private'::trip_type, 5, 4, 18999, 8, 2, 6, 'muv'::vehicle_category, 'Private Toyota Innova Crysta with driver for 5 days.', '3-star hotels and a deluxe houseboat.', array['Kochi airport','Ernakulam railway station']::text[], array['Kochi airport']::text[], array['Ernakulam']::district[], array['Private Innova Crysta','4 nights stay','Daily breakfast','Houseboat full board','Driver allowance and tolls']::text[], array['Flights/trains','Entry tickets','Lunches and dinners except houseboat']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, true, false, 4.8, 151, 520, '2026-04-01T21:20:55.260Z', '2026-04-01T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000006', 'vagamon-group-camping', 'Vagamon Meadows Group Camping', 'Overnight tents, campfire, pine forest and optional paragliding.', 'A sociable weekend for friend groups and colleagues. Camp on a private meadow with a campfire and barbecue, walk the pine forest at dawn and try paragliding with certified pilots (weather permitting).', 'd0000000-0000-4000-8000-000000000003', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000003', array['group','adventure','weekend','budget']::package_category[], 'group'::trip_type, 2, 1, 2999, 0, 8, 17, 'tempo_traveller'::vehicle_category, 'AC Tempo Traveller from Kochi or Kottayam.', 'Dome tents, 3 per tent, shared washrooms.', array['Kochi — Vyttila Hub','Kottayam KSRTC']::text[], array['Kochi — Vyttila Hub','Kottayam KSRTC']::text[], array['Ernakulam','Kottayam']::district[], array['Transport','Tent stay','Dinner, barbecue & breakfast','Campfire','Trip captain']::text[], array['Paragliding (₹3,500)','Lunch']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, true, 4.6, 120, 455, '2026-10-13T21:20:55.260Z', '2026-10-13T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000007', 'sabarimala-pilgrimage-package', 'Sabarimala Mandala Season Pilgrimage', 'Hassle-free travel to Pamba with Erumely stop and return — by bus or tempo traveller.', 'Operated during the Mandala–Makaravilakku season for groups of devotees. Includes the traditional Erumely stop, transport to Pamba and return after darshan. Virtual Queue booking assistance is provided.', 'd0000000-0000-4000-8000-000000000015', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000005', array['pilgrimage','group','budget']::package_category[], 'group'::trip_type, 2, 1, 1899, 0, 10, 45, 'tourist_bus'::vehicle_category, 'Tourist bus or tempo traveller depending on group size.', 'Rest stop at Pamba / Nilakkal (basic).', array['Thiruvananthapuram Thampanoor','Kollam','Kottayam']::text[], array['Thiruvananthapuram Thampanoor','Kollam','Kottayam']::text[], array['Thiruvananthapuram','Kollam','Kottayam']::district[], array['Return transport','Virtual Queue booking help','Driver bata and tolls','Coordinator']::text[], array['Food','Offerings','Accommodation upgrades']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, false, 4.5, 210, 1320, '2026-10-28T21:20:55.260Z', '2026-10-28T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000008', 'varkala-cliff-beach-weekend', 'Varkala Cliff & Beach Weekend', 'Cliff-top stay, sunset cafés, a surf lesson and an Ayurvedic massage.', 'A laid-back coastal weekend on Varkala’s North Cliff: beginner surf session, Kappil backwater kayak and a 60-minute Abhyanga massage.', 'd0000000-0000-4000-8000-000000000006', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000001', array['couple','weekend']::package_category[], 'private'::trip_type, 3, 2, 8999, 0, 2, 4, 'sedan'::vehicle_category, 'Private sedan from Thiruvananthapuram airport / station.', 'Boutique cliff-top resort.', array['Thiruvananthapuram airport','Varkala Sivagiri station']::text[], array['Thiruvananthapuram airport','Varkala Sivagiri station']::text[], array['Thiruvananthapuram','Kollam']::district[], array['Transfers','2 nights stay','Breakfast','Surf lesson','Ayurvedic massage']::text[], array['Lunch and dinner','Kayak rental']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, false, 4.6, 64, 190, '2026-09-13T21:20:55.260Z', '2026-09-13T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000009', 'kerala-honeymoon-7-days', 'Kerala Honeymoon — Hills, Lake & Sea', '7 days of Munnar, Thekkady, a private houseboat and Kovalam with romantic extras.', 'Candle-light dinners, flower bed decorations, a private houseboat night and a beach resort finale. Fully private with a dedicated chauffeur.', 'd0000000-0000-4000-8000-000000000001', array['d0000000-0000-4000-8000-000000000005','d0000000-0000-4000-8000-000000000004','d0000000-0000-4000-8000-000000000007']::uuid[], 'a0000000-0000-4000-8000-000000000001', array['honeymoon','couple','luxury','multi_day']::package_category[], 'private'::trip_type, 7, 6, 42999, 12, 2, 2, 'sedan'::vehicle_category, 'Private sedan with chauffeur for 7 days.', '4-star resorts and a premium houseboat.', array['Kochi airport']::text[], array['Thiruvananthapuram airport']::text[], array['Ernakulam']::district[], array['All transfers','6 nights stay','Breakfast daily','Candle-light dinner','Houseboat full board','Honeymoon decorations']::text[], array['Flights','Entry tickets','Personal expenses']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, true, false, 4.9, 73, 140, '2026-01-31T21:20:55.260Z', '2026-01-31T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000010', 'thekkady-spice-wildlife', 'Thekkady Spice & Wildlife Getaway', 'Periyar boat safari, spice plantation walk and a jungle-edge resort.', 'Two days in the cardamom hills around Periyar Tiger Reserve with a lake safari, plantation walk and an evening Kalaripayattu performance.', 'd0000000-0000-4000-8000-000000000005', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000001', array['family','weekend']::package_category[], 'private'::trip_type, 2, 1, 5499, 0, 2, 6, 'suv'::vehicle_category, 'Private SUV from Kochi or Kottayam.', 'Jungle-edge resort.', array['Kochi','Kottayam']::text[], array['Kochi','Kottayam']::text[], array['Ernakulam','Kottayam']::district[], array['Private SUV','1 night stay','Breakfast & dinner','Spice plantation tour']::text[], array['Boat safari tickets','Lunch']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, false, 4.5, 52, 160, '2026-11-07T21:20:55.260Z', '2026-11-07T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000011', 'fort-kochi-heritage-day', 'Fort Kochi Heritage & Food Walk', 'Guided half-day walk through Mattancherry, Jew Town and Fort Kochi’s cafés.', 'A 6-hour guided walk and short drives covering Chinese fishing nets, St. Francis Church, Mattancherry Palace, the Paradesi Synagogue and spice warehouses, with tasting stops.', 'd0000000-0000-4000-8000-000000000008', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000001', array['one_day','couple','budget']::package_category[], 'group'::trip_type, 1, 0, 1199, 0, 2, 12, 'tempo_traveller'::vehicle_category, 'Shared AC vehicle between stops.', 'Not applicable.', array['Fort Kochi — Vasco da Gama Square','Ernakulam boat jetty']::text[], array['Fort Kochi — Vasco da Gama Square','Ernakulam boat jetty']::text[], array['Ernakulam']::district[], array['Licensed guide','Food tasting (5 stops)','Ferry ticket']::text[], array['Entry tickets','Shopping']::text[], 'Free cancellation up to 48 hours before departure. 50% refund within 48 hours. No refund for no-shows.', '{}'::date[], 'published'::package_status, false, false, 4.7, 133, 720, '2026-11-17T21:20:55.260Z', '2026-11-17T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000012', 'kovalam-ponmudi-combo', 'Ponmudi Hills & Kovalam Beach Combo', 'Morning in the clouds at Ponmudi, sunset at Kovalam — one easy day from Trivandrum.', 'Climb Ponmudi’s 22 hairpin bends to the tea-covered hilltop, stop at Golden Valley, then head to Kovalam’s Lighthouse Beach for sunset.', 'd0000000-0000-4000-8000-000000000011', array['d0000000-0000-4000-8000-000000000007']::uuid[], 'a0000000-0000-4000-8000-000000000005', array['one_day','family','budget']::package_category[], 'private'::trip_type, 1, 0, 999, 0, 2, 12, 'tempo_traveller'::vehicle_category, 'Private car or tempo traveller based on group size.', 'Not applicable.', array['Thiruvananthapuram city','Thiruvananthapuram airport']::text[], array['Thiruvananthapuram city','Thiruvananthapuram airport']::text[], array['Thiruvananthapuram']::district[], array['Private vehicle','Fuel and tolls','Driver bata']::text[], array['Food','Entry tickets']::text[], 'Free cancellation up to 48 hours before departure. 50% refund within 48 hours. No refund for no-shows.', '{}'::date[], 'published'::package_status, false, false, 4.4, 40, 230, '2026-11-22T21:20:55.260Z', '2026-11-22T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000013', 'bekal-kannur-theyyam-tour', 'Bekal & Kannur Theyyam Trail', 'Bekal Fort, Valiyaparamba backwaters and a night Theyyam ritual with a local guide.', 'A North Malabar cultural journey timed with Theyyam season, combining Bekal Fort, a backwater kayak and Muzhappilangad drive-in beach.', 'd0000000-0000-4000-8000-000000000010', array['d0000000-0000-4000-8000-000000000019']::uuid[], 'a0000000-0000-4000-8000-000000000002', array['multi_day','couple','custom']::package_category[], 'private'::trip_type, 4, 3, 15499, 0, 2, 6, 'suv'::vehicle_category, 'Private SUV from Kozhikode or Kannur airport.', 'Beach resort and heritage homestay.', array['Kannur airport','Kozhikode railway station']::text[], array['Kannur airport','Kozhikode railway station']::text[], array['Kannur','Kozhikode','Kasaragod']::district[], array['Private SUV','3 nights stay','Breakfast & dinner','Theyyam guide','Kayak session']::text[], array['Lunch','Entry tickets']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, false, 4.8, 29, 70, '2026-09-28T21:20:55.260Z', '2026-09-28T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000014', 'kumarakom-lake-luxury', 'Kumarakom Lake Resort Luxury Stay', 'Two nights at a lakefront villa, bird sanctuary walk and sunset cruise.', 'Slow luxury on Vembanad: private pool villa, Kumarakom bird sanctuary at dawn, a sunset motor-boat cruise to Pathiramanal and an Ayurvedic spa session.', 'd0000000-0000-4000-8000-000000000012', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000001', array['luxury','couple','honeymoon']::package_category[], 'private'::trip_type, 3, 2, 24999, 0, 2, 3, 'premium'::vehicle_category, 'Chauffeured premium sedan from Kochi airport.', 'Lakefront pool villa.', array['Kochi airport']::text[], array['Kochi airport']::text[], array['Ernakulam']::district[], array['Premium transfers','2 nights villa','All meals','Sunset cruise','Spa session']::text[], array['Alcohol','Additional spa treatments']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', '{}'::date[], 'published'::package_status, false, false, 4.9, 41, 85, '2026-06-30T21:20:55.260Z', '2026-06-30T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000015', 'munroe-island-canoe-day', 'Munroe Island Sunrise Canoe', 'Paddle village canals at sunrise and visit coir makers and prawn farms.', 'A gentle, eco-friendly morning in Kollam’s Munroe Island by country canoe with a local boatman, followed by a traditional breakfast at a village home.', 'd0000000-0000-4000-8000-000000000016', '{}'::uuid[], 'a0000000-0000-4000-8000-000000000005', array['one_day','family','budget']::package_category[], 'group'::trip_type, 1, 0, 899, 0, 2, 10, 'sedan'::vehicle_category, 'Self-arrival or pickup from Kollam (add-on).', 'Not applicable.', array['Munroe Island jetty','Kollam KSRTC (add-on)']::text[], array['Munroe Island jetty','Kollam KSRTC (add-on)']::text[], array['Kollam']::district[], array['Country canoe with boatman','Village breakfast','Coir-making demo']::text[], array['Transport to Munroe Island']::text[], 'Free cancellation up to 48 hours before departure. 50% refund within 48 hours. No refund for no-shows.', '{}'::date[], 'published'::package_status, false, false, 4.6, 58, 260, '2026-11-25T21:20:55.260Z', '2026-11-25T21:20:55.260Z'),
  ('b0000000-0000-4000-8000-000000000016', 'luxury-kerala-coach-tour', 'Luxury Coach Kerala Grand Tour', 'A 6-day coach tour for large groups — Kochi, Munnar, Thekkady, Alleppey and Kovalam.', 'Built for corporate groups, associations and large families: Volvo multi-axle coach, 3-star+ hotels, a tour manager and all sightseeing.', 'd0000000-0000-4000-8000-000000000008', array['d0000000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000005','d0000000-0000-4000-8000-000000000004','d0000000-0000-4000-8000-000000000007']::uuid[], 'a0000000-0000-4000-8000-000000000005', array['group','luxury','multi_day']::package_category[], 'group'::trip_type, 6, 5, 21999, 0, 20, 41, 'luxury_coach'::vehicle_category, 'Volvo multi-axle luxury coach.', '3-star and 4-star hotels, twin sharing.', array['Kochi airport','Ernakulam Junction']::text[], array['Thiruvananthapuram airport']::text[], array['Ernakulam']::district[], array['Luxury coach','5 nights stay','Breakfast & dinner','Tour manager','Shared houseboat cruise']::text[], array['Lunch','Entry tickets','Flights']::text[], 'Free cancellation up to 7 days before travel. 50% refund between 7 and 3 days. No refund within 72 hours of departure. Weather-related cancellations by the operator are fully refunded.', array['2026-12-15','2027-01-12','2027-02-09']::date[], 'published'::package_status, false, false, 4.5, 22, 48, '2026-11-26T21:20:55.260Z', '2026-11-26T21:20:55.260Z')
