insert into public.package_itineraries (id, package_id, day_number, title, description, meals, stay) values
  ('60010001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000001', 1, 'Waterfalls and rainforest', 'Pickup 7:00 am · Athirappilly falls by 9:30 · Vazhachal · Sholayar drive · Lunch · Drop by 6:30 pm.', array['Lunch']::text[], null),
  ('60020001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000002', 1, 'Kochi to Munnar', 'Depart 6:00 am, breakfast en route, Cheeyappara falls, spice garden, check-in and campfire.', array['Breakfast','Dinner']::text[], 'Valley-view resort'),
  ('60020002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000002', 2, 'Eravikulam & Mattupetty', 'Nilgiri tahr at Eravikulam, Tea Museum, Mattupetty dam boating, Echo Point.', array['Breakfast','Dinner']::text[], 'Valley-view resort'),
  ('60020003-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000002', 3, 'Top Station & return', 'Optional sunrise at Top Station, checkout, return to Kochi by 7:00 pm.', array['Breakfast']::text[], null),
  ('60030001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000003', 1, 'Board and cruise', 'Check-in 12:00 pm, cruise through Vembanad and Kuttanad canals, village walk, sunset anchor.', array['Lunch','Snacks','Dinner']::text[], 'Premium houseboat'),
  ('60030002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000003', 2, 'Morning on the lake', 'Breakfast on deck, checkout 9:00 am.', array['Breakfast']::text[], null),
  ('60040001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000004', 1, 'Into the hills', 'Thamarassery ghat drive, Pookode lake kayaking, camp check-in and barbecue.', array['Lunch','Dinner']::text[], 'Tented camp'),
  ('60040002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000004', 2, 'Chembra Peak trek', 'Guided trek to the heart lake (permits included), evening at Banasura dam.', array['Breakfast','Lunch','Dinner']::text[], 'Plantation homestay'),
  ('60040003-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000004', 3, 'Safari & Edakkal', 'Dawn Muthanga safari, Edakkal caves, return to Kozhikode by 7:30 pm.', array['Breakfast','Lunch']::text[], null),
  ('60050001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000005', 1, 'Arrive Kochi', 'Fort Kochi heritage walk, Chinese fishing nets at sunset, Kathakali show.', '{}'::text[], 'Kochi'),
  ('60050002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000005', 2, 'Kochi to Munnar', 'Scenic drive with waterfall stops, spice garden, evening at leisure.', array['Breakfast']::text[], 'Munnar'),
  ('60050003-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000005', 3, 'Munnar sightseeing', 'Eravikulam, Tea Museum, Mattupetty dam and Echo Point.', array['Breakfast']::text[], 'Munnar'),
