  ('60050005-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000005', 5, 'Alleppey houseboat', 'Board at noon, cruise Vembanad, drop at Kochi airport next morning (add-on night) or same evening.', array['Breakfast','Lunch']::text[], null),
  ('60060001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000006', 1, 'Up to the meadows', 'Depart 7:00 am, Thangalpara, Vagamon meadows, camp games, barbecue night.', array['Dinner']::text[], 'Meadow campsite'),
  ('60060002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000006', 2, 'Pine forest & return', 'Sunrise walk, pine forest, optional paragliding, return by 6:00 pm.', array['Breakfast']::text[], null),
  ('60070001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000007', 1, 'Departure to Erumely and Pamba', 'Evening departure, Erumely Petta Thullal stop, reach Nilakkal / Pamba.', '{}'::text[], null),
  ('60070002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000007', 2, 'Darshan and return', 'Climb to Sannidhanam, darshan, return journey.', '{}'::text[], null),
  ('60080001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000008', 1, 'Arrive Varkala', 'Transfer, check-in, sunset on North Cliff.', '{}'::text[], 'Cliff-top resort'),
  ('60080002-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000008', 2, 'Surf & spa', 'Morning surf lesson, afternoon Ayurveda, Kappil sunset.', array['Breakfast']::text[], 'Cliff-top resort'),
  ('60080003-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000008', 3, 'Departure', 'Papanasam beach, Janardanaswamy temple, drop.', array['Breakfast']::text[], null),
  ('60090001-0000-4000-8000-000000000000', 'b0000000-0000-4000-8000-000000000009', 1, 'Kochi to Munnar', 'Airport pickup and scenic drive to the hills.', '{}'::text[], 'Munnar'),
