  ('e0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000004', 'Maruti Swift — city & airport', 'Maruti Suzuki', 'Swift', 2023, 'hatchback'::vehicle_category, 4, '2 cabin bags', true, true, 'per_km'::pricing_unit, 12, 1500, 'Thrissur'::district, 'Thrissur town / Kochi airport', array['Music system','Phone charger','First-aid kit']::text[], 'Compact and economical for couples and solo travellers. Driver knows central Kerala well.', true, 'approved'::vehicle_listing_status, true, 4.9, 41, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000004', 'Toyota Etios sedan', 'Toyota', 'Etios', 2021, 'sedan'::vehicle_category, 4, '2 large bags', true, true, 'per_km'::pricing_unit, 14, 2000, 'Thrissur'::district, 'Thrissur / Guruvayur', array['Bottled water','Phone charger','Child seat on request']::text[], 'Comfortable sedan with a big boot — ideal for temple trips and airport transfers.', true, 'approved'::vehicle_listing_status, true, 4.8, 46, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
