  ('e0000000-0000-4000-8000-000000000004', 'a0000000-0000-4000-8000-000000000001', 'Mahindra XUV500', 'Mahindra', 'XUV500', 2021, 'suv'::vehicle_category, 6, '3 large bags', true, true, 'per_day'::pricing_unit, 4200, 4200, 'Ernakulam'::district, 'Kochi / Aluva', array['Sunroof','Rear AC','USB charging']::text[], 'Powerful SUV for hill-station ghats — Munnar, Vagamon and Wayanad.', true, 'approved'::vehicle_listing_status, true, 4.7, 38, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
