  ('e0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000005', 'Force Traveller 12-seater', 'Force', 'Traveller', 2023, 'tempo_traveller'::vehicle_category, 12, 'Roof carrier + rear boot', true, true, 'per_km'::pricing_unit, 26, 6000, 'Thiruvananthapuram'::district, 'Thiruvananthapuram / Kollam', array['Push-back seats','Music system','Reading lights','Roof carrier']::text[], 'Perfect for extended families and friend groups on weekend trips.', true, 'approved'::vehicle_listing_status, true, 4.6, 94, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000003', 'Force Traveller 17-seater', 'Force', 'Traveller', 2022, 'tempo_traveller'::vehicle_category, 17, 'Rear boot', true, true, 'per_km'::pricing_unit, 30, 7500, 'Idukki'::district, 'Kochi / Kottayam', array['Push-back seats','LED TV','Music system']::text[], 'Used on Highrange group departures; available for private hire on weekdays.', true, 'approved'::vehicle_listing_status, true, 4.5, 33, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000005', 'Tata mini bus 26-seater', 'Tata', 'Starbus', 2021, 'mini_bus'::vehicle_category, 26, 'Under-floor storage', true, true, 'per_km'::pricing_unit, 38, 9000, 'Thiruvananthapuram'::district, 'Thiruvananthapuram', array['Mic & speakers','Push-back seats']::text[], 'School trips, office outings and wedding guest transfers.', true, 'approved'::vehicle_listing_status, true, 4.4, 52, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000005', 'Tourist bus 45-seater', 'Ashok Leyland', 'Viking', 2020, 'tourist_bus'::vehicle_category, 45, 'Large under-floor storage', true, true, 'per_km'::pricing_unit, 55, 14000, 'Thiruvananthapuram'::district, 'Anywhere in south Kerala', array['Mic & speakers','LED TV','Push-back seats']::text[], 'Classic Kerala tourist bus for large groups and pilgrimages.', false, 'approved'::vehicle_listing_status, true, 4.3, 61, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000005', 'Volvo luxury coach 41-seater', 'Volvo', 'B11R', 2022, 'luxury_coach'::vehicle_category, 41, 'Large under-floor storage', true, true, 'per_km'::pricing_unit, 85, 22000, 'Ernakulam'::district, 'Kochi', array['Reclining seats','Washroom','Wi-Fi','Charging points']::text[], 'Premium multi-axle coach for corporate tours and long-distance groups.', true, 'approved'::vehicle_listing_status, true, 4.7, 25, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000002', 'Mercedes-Benz E-Class', 'Mercedes-Benz', 'E-Class', 2023, 'premium'::vehicle_category, 3, '2 large bags', true, true, 'per_day'::pricing_unit, 12000, 12000, 'Kozhikode'::district, 'Kozhikode / Calicut airport', array['Chauffeur in uniform','Bottled water','Wi-Fi']::text[], 'Chauffeured luxury for weddings, VIP guests and honeymoon transfers.', true, 'pending'::vehicle_listing_status, false, 0, 0, '2026-09-01T09:00:00.000Z', '2026-09-01T09:00:00.000Z')
