insert into public.reviews (id, package_id, vehicle_id, operator_id, author_name, author_city, rating, title, body, travel_month, status, created_at, updated_at) values
  ('10000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', null, 'a0000000-0000-4000-8000-000000000003', 'Arun V', 'Kochi', 5, 'Perfectly paced weekend', 'Trip captain was fantastic and the resort view was stunning. The campfire night was a highlight.', 'October 2026', 'published'::review_status, '2026-11-17T10:15:00.000Z', '2026-11-17T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000002', 'b0000000-0000-4000-8000-000000000002', null, 'a0000000-0000-4000-8000-000000000003', 'Meera S', 'Bengaluru', 4, 'Great value', 'Lovely group and comfortable traveller. Would have liked more time at Eravikulam.', 'September 2026', 'published'::review_status, '2026-11-14T10:15:00.000Z', '2026-11-14T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000003', 'b0000000-0000-4000-8000-000000000003', null, 'a0000000-0000-4000-8000-000000000006', 'Rohit & Neha', 'Mumbai', 5, 'Best food of our trip', 'The chef’s karimeen pollichathu was unforgettable. Clean, quiet and very private.', 'October 2026', 'published'::review_status, '2026-11-11T10:15:00.000Z', '2026-11-11T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000004', 'b0000000-0000-4000-8000-000000000001', null, 'a0000000-0000-4000-8000-000000000004', 'Fathima K', 'Thrissur', 5, 'Safe and punctual driver', 'Jomon chettan was on time, drove carefully and knew the best viewpoints.', 'August 2026', 'published'::review_status, '2026-11-08T10:15:00.000Z', '2026-11-08T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000005', 'b0000000-0000-4000-8000-000000000005', null, 'a0000000-0000-4000-8000-000000000001', 'The Agarwal family', 'Jaipur', 5, 'Kids loved every day', 'Hotels were well chosen and the houseboat was the cherry on top.', 'July 2026', 'published'::review_status, '2026-11-05T10:15:00.000Z', '2026-11-05T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000006', 'b0000000-0000-4000-8000-000000000004', null, 'a0000000-0000-4000-8000-000000000002', 'Sanjay P', 'Chennai', 4, 'Tough but rewarding trek', 'Chembra is steep — the guide was patient. Camp food was simple but good.', 'October 2026', 'published'::review_status, '2026-11-02T10:15:00.000Z', '2026-11-02T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000007', 'b0000000-0000-4000-8000-000000000006', null, 'a0000000-0000-4000-8000-000000000003', 'Team Pixel (Demo)', 'Kochi', 5, 'Ideal team outing', 'Smooth logistics for 15 of us. Paragliding was worth it.', 'September 2026', 'published'::review_status, '2026-10-30T10:15:00.000Z', '2026-10-30T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000008', null, 'e0000000-0000-4000-8000-000000000005', 'a0000000-0000-4000-8000-000000000003', 'Diya R', 'Pune', 5, 'Kolukkumalai sunrise!', 'Bumpy but exhilarating ride; driver stopped for every photo.', 'October 2026', 'published'::review_status, '2026-10-27T10:15:00.000Z', '2026-10-27T10:15:00.000Z'),
  ('10000000-0000-4000-8000-000000000009', 'b0000000-0000-4000-8000-000000000011', null, 'a0000000-0000-4000-8000-000000000001', 'Tom H', 'London', 4, 'Lovely guide', 'Lots of history and great food stops. A little rushed at the end.', 'November 2026', 'pending'::review_status, '2026-10-24T10:15:00.000Z', '2026-10-24T10:15:00.000Z')
